// and executionStats.totalKeysExamined ~= nReturned (efficient index use)
print(plan.executionStats.totalKeysExamined, plan.executionStats.nReturned);

// 1) Diagnose
const before = db.events
  .find({ tenantId: "acme", type: "login" })
  .sort({ ts: -1 })
  .explain("executionStats");
// winningPlan shows the plan tree; a top/nested COLLSCAN means a missing index
printjson(before.queryPlanner.winningPlan);            // look for 'COLLSCAN' -> bad
print(before.executionStats.totalDocsExamined,         // huge
      before.executionStats.nReturned);                // small -> red flag

// 2) Fix: selective compound index following ESR (equality -> sort)
db.events.createIndex({ tenantId: 1, type: 1, ts: -1 });

// 3) Verify
const after = db.events
  .find({ tenantId: "acme", type: "login" })
  .sort({ ts: -1 })
  .explain("executionStats");
printjson(after.queryPlanner.winningPlan);             // now 'IXSCAN' (+ FETCH), no 'SORT' -> good
print(after.executionStats.totalDocsExamined,
